package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check for creating an owner: rejects a request whose derived
 * {@link Owner#getIdentityKey() identity key} — normalized telephone, email and household id — equals
 * that of an existing owner. It subsumes the former separate telephone, email and household checks:
 * because the telephone is part of the key, two members of one household with different telephones
 * have different keys and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link AssignHousehold} so the new owner carries its final {@code householdId}, and
 * before {@link SaveOwner} so a collision is rejected with 409 before anything is persisted. Only
 * owners sharing the (already normalized) telephone can share the whole key, so those are the
 * candidates compared.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateIdentityException {
        String identityKey = owner.getIdentityKey();
        for (Owner existing : ownerRepository.findByTelephone(owner.getTelephone())) {
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, @Val Boolean bulkSignupWarning, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner, bulkSignupWarning);
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Resolves whether the owner response should carry a bulk-signup warning and publishes it for the
 * responder. The warning is raised once more than {@value #BULK_SIGNUP_THRESHOLD} owners have
 * already been registered on the current date, matching the per-day accumulation counted by
 * {@link EnsureDailyOwnerLimit}. Runs before the responder so both the create and read responses
 * carry the flag.
 */
public class ResolveBulkSignupWarning {

    /** Owners registered today beyond this count raise the bulk-signup warning. */
    static final int BULK_SIGNUP_THRESHOLD = 80;

    public void service(OwnerRepository ownerRepository, Out<Boolean> bulkSignupWarning) {
        long count = ownerRepository.countByRegistrationDate(LocalDate.now());
        bulkSignupWarning.set(count > BULK_SIGNUP_THRESHOLD);
    }
}

